RULES = {
    "REQUESTED": {"approve": ["approver"], "reject": ["approver"], "cancel": ["requester"]},
    "APPROVED": {"execute": ["operator"]},
    "DONE": {},
}

def actions_for(roles, status):
    return [a for a, allowed in RULES[status].items() if any(r in roles for r in allowed)]

print(actions_for(["requester"], "REQUESTED"))  # ['cancel']
print(actions_for(["approver"], "REQUESTED"))   # ['approve', 'reject']
print(actions_for(["approver"], "DONE"))        # []

NEXT = {"REQUESTED": ["APPROVED", "REJECTED", "CANCELED"],
        "APPROVED": ["DONE", "FAILED"], "FAILED": ["APPROVED"]}

def move(frm, to):
    if to not in NEXT.get(frm, []):
        raise ValueError(f"{frm} -> {to} 는 안 된다")
    return to

print(move("REQUESTED", "APPROVED"))  # APPROVED
move("REQUESTED", "DONE")             # ValueError: REQUESTED -> DONE 는 안 된다

import re
def mask_name(n):
    return n[0] + "*" if len(n) <= 2 else n[0] + "*" * (len(n) - 2) + n[-1]
def mask_acct(a):
    return re.sub(r"\d(?=\d{4})", "*", a)

print(mask_name("홍길동"), mask_name("김철"), mask_acct("1234567890"))
# 홍*동 김* ******7890
